<?php
header('Content-Type: application/json; charset=utf-8');
require_once __DIR__ . '/../Config/mikrotik.php';
require_once __DIR__ . '/../library/routeros_api.class.php';
try{$config=new MikroTikConfig();$router=$config->getRouter();if(!$router){echo json_encode(['status'=>'offline','message'=>'Router tidak tersedia']);exit;}$api=new RouterosAPI();$api->debug=false;if(!$api->connect($router['ip_address'],$router['username'],$router['password'],$router['api_port'])){echo json_encode(['status'=>'offline','message'=>'Router tidak dapat terhubung']);exit;}$filter=$api->comm('/ip/firewall/filter/print');$nat=$api->comm('/ip/firewall/nat/print');$mangle=$api->comm('/ip/firewall/mangle/print');$api->disconnect();$map=function($items){$rows=[];foreach($items as $x){$rows[]=['id'=>$x['.id']??'','chain'=>$x['chain']??'-','action'=>$x['action']??'-','protocol'=>$x['protocol']??'','src'=>$x['src-address']??'','dst'=>$x['dst-address']??'','in_interface'=>$x['in-interface']??'','out_interface'=>$x['out-interface']??'','comment'=>$x['comment']??'','disabled'=>isset($x['disabled']),'dynamic'=>isset($x['dynamic']),'bytes'=>$x['bytes']??0,'packets'=>$x['packets']??0];}return $rows;};echo json_encode(['status'=>'online','router'=>$router['router_name'],'filter'=>$map($filter),'nat'=>$map($nat),'mangle'=>$map($mangle)]);}catch(Throwable $e){http_response_code(500);echo json_encode(['status'=>'error','message'=>$e->getMessage()]);}